import{z as l,x as d,o as r,c as B,q as i,j as s,D as e,d as E,s as n,S as A,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"硬中断与软中断","description":"","frontmatter":{"title":"硬中断与软中断","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hardirq-softirq.md","filePath":"cs/hardirq-softirq.md","lastUpdated":1791413859000}'),p={name:"cs/hardirq-softirq.md"};function D(c,a,h,m,u,f){const o=d("Mermaid");return r(),B("div",null,[a[2]||(a[2]=i('<h1 id="硬中断与软中断" tabindex="-1">硬中断与软中断 <a class="header-anchor" href="#硬中断与软中断" aria-label="Permalink to &quot;硬中断与软中断&quot;">​</a></h1><div class="epigraph"><p>硬中断上下文不能睡眠；软中断在开中断之后跑，仍不许睡眠，只是把可推迟的工作从 IRQ 线的关掩码下挪出来。</p><footer>—— 据 Bovet and Cesati, Understanding the Linux Kernel；Love, Linux Kernel Development 整理</footer></div><p><a href="/cs/interrupt-bottom-half">上一课</a>把设备 IRQ 拆成短上半与可推迟下半，但把 Linux 里「硬中断 / 软中断」两种<strong>上下文</strong>留白。缺口是：上半部对应硬 IRQ——可能关该线甚至关本地中断；下半部里有一类仍在中断返回前、以软中断形式跑，<strong>仍然不能睡眠</strong>，只是不再占用那条硬 IRQ 的关掩码。本课钉这两种上下文，不把 tasklet 队列写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若凡下半部都可以睡，网卡收包处理会去拿睡眠锁、去调页，硬中断延迟的上界就丢了。若凡下半部都关硬中断，其他设备会被一次协议处理饿死。缺口不是再讲<a href="/cs/exception-interrupt-entry">异常入口</a>，而是承认内核里至少两档：硬中断上下文（ISR）、软中断上下文（开硬中断、禁睡眠）。工作线程是第三档，下一课才请出来。</p><p><span class="marginnote">软中断按类型串行或分 CPU 串行，避免同一软中断在多核上重入同一全局结构。本课只要求「能推迟、仍不能睡」，不写编号表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬 IRQ：应答设备、清原因、把描述符链入队列、标记对应软中断 pending，尽快 <code>iret</code> 路径。返回用户或返回内核前，若 pending，关抢占、开硬中断，跑软中断：组包、提交套接字缓冲、<code>wakeup</code> 阻塞在<a href="/cs/syscall-path">系统调用路径</a>上的线程。软中断里禁止 <code>schedule</code> 进入睡眠。</p><p><span class="marginnote">术语翻译：<code>iret</code> 是 x86 的「从中断返回」指令。「尽快走 iret 路径」意思是 ISR 只做撕快递面单这一步——数据挂进队列就退出中断，重活留给软中断。若在 ISR 里直接组包，下一个网卡中断就可能被推迟几毫秒，对延迟敏感的设备是灾难。</span></p><p><span class="marginnote">常见误区：初学者容易以为「禁睡眠」只是风格建议。实际上软中断里若调用了会睡的函数，调度器会试图切走当前上下文，而中断上下文没有可以挂起的「进程」——轻则触发 scheduling while atomic 警告，重则 CPU 卡死在根本回不来的切换里。</span></p>',10)),(r(),s(A,null,{default:e(()=>[n(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20HW%5B%22%E7%A1%AC%20IRQ%22%5D%20--%3E%20ISR%5B%22%E7%A1%AC%E4%B8%AD%E6%96%AD%E4%B8%8A%E4%B8%8B%E6%96%87%3A%20%E6%B8%85%E8%AE%BE%E5%A4%87%22%5D%0A%20%20ISR%20--%3E%20PEND%5B%22%E6%A0%87%E8%AE%B0%E8%BD%AF%E4%B8%AD%E6%96%AD%22%5D%0A%20%20PEND%20--%3E%20SOFT%5B%22%E8%BD%AF%E4%B8%AD%E6%96%AD%E4%B8%8A%E4%B8%8B%E6%96%87%3A%20%E5%A4%84%E7%90%86%E3%80%81%E5%94%A4%E9%86%92%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"与用户路径的会合点仍是等待队列：调用在路径里睡，软中断里唤醒。本课不写队列 API。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"两档让延迟分层：硬中断延迟由 ISR 长度决定；软中断延迟还叠加在返回路径上，但其他硬 IRQ 可以插进来。共享数据因此要分清「与硬 IRQ 并发」还是「只与软中断并发」——锁与关中断的搭配是后课，本课只预告：硬 IRQ 里不能拿睡眠锁。",-1)),(r(),s(A,null,{default:e(()=>[n(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%BD%AF%E4%B8%AD%E6%96%AD%E5%BC%80%E5%A7%8B%E6%89%A7%E8%A1%8C%22%5D%20--%3E%20B%5B%22%E6%AD%A4%E6%97%B6%E6%9C%AC%E5%9C%B0%E7%A1%AC%E4%B8%AD%E6%96%AD%E5%B7%B2%E5%BC%80%E5%90%AF%22%5D%0A%20%20B%20--%3E%20C%7B%22%E6%96%B0%E8%AE%BE%E5%A4%87%20IRQ%20%E5%88%B0%E6%9D%A5%3F%22%7D%0A%20%20C%20--%20%22%E6%98%AF%22%20--%3E%20D%5B%22%E7%A1%AC%20IRQ%20%E6%8A%A2%E5%8D%A0%E8%BD%AF%E4%B8%AD%E6%96%AD%22%5D%0A%20%20D%20--%3E%20E%5B%22ISR%20%E5%8F%AA%E6%A0%87%E8%AE%B0%20pending%20%E5%B0%B1%E8%BF%94%E5%9B%9E%22%5D%0A%20%20E%20--%3E%20A%0A%20%20C%20--%20%22%E5%90%A6%22%20--%3E%20F%5B%22%E8%B7%91%E5%AE%8C%E5%89%A9%E4%BD%99%E8%BD%AF%E4%B8%AD%E6%96%AD%22%5D%0A%20%20F%20--%3E%20G%5B%22%E8%BF%94%E5%9B%9E%E8%A2%AB%E4%B8%AD%E6%96%AD%E7%9A%84%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">为什么重要：同一段数据若既被硬 IRQ 摸、又被软中断摸，只加自旋锁并不够——硬 IRQ 可能在同一 CPU 上、软中断正持锁时插进来，再拿同一把锁就死锁。所以内核要用「关本地中断再加锁」这类搭配；选错并发档位，锁就形同虚设。</span></p><p><a href="/cs/io-dma">I/O 与 DMA</a> 仍只提供完成通知；本课不重讲总线。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 <code>BH</code> 历史名与 <code>softirq</code> 逐一对照成考古。NMI 几乎不能进这套推迟，后面单独一课。也不把用户信号当软中断：信号是进程的软件中断，对象不同。</p><p>后课默认：下半部里仍有不能睡的一档。更重、允许睡眠的推迟要交给专门机制，下一课讲 tasklet 与 workqueue。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>硬中断短、可关线；软中断可推迟但仍不能睡眠。</li><li>唤醒阻塞系统调用发生在软中断或更后的线程里。</li><li>可睡的推迟队列是下一课。</li><li>出处：Bovet and Cesati；Love, <em>LKD</em>。</li></ul>',7))])}const _=l(p,[["render",D]]);export{C as __pageData,_ as default};
